mapper.select:
select id, user_id, platform, openid, nickname, avatar, email, bind_time
from user_oauth
where platform = #{platform}
  and openid = #{openid}
limit 1

select id, user_id, platform, openid, nickname, avatar, email, bind_time
from user_oauth
where user_id = #{userId}
  and platform = #{platform}
limit 1
